SELECT 'gen980-measure' AS marker,
 (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE USER_NAME = 'CLAUDE_READER' AND START_TIME >= '2026-10-28') AS reader_queries,
 (SELECT COUNT(DISTINCT TO_DATE(START_TIME)) FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE USER_NAME = 'CLAUDE_READER' AND START_TIME >= '2026-10-28') AS reader_days,
 (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE USER_NAME = 'CLAUDE_READER' AND START_TIME >= '2026-10-28' AND EXECUTION_STATUS <> 'SUCCESS') AS reader_failed,
 (SELECT ROUND(COALESCE(SUM(CREDITS_USED), 0), 3) FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY WHERE WAREHOUSE_NAME = 'CLAUDE_WH' AND START_TIME >= '2026-10-28') AS claude_wh_credits,
 (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.CORTEX_AI_FUNCTIONS_USAGE_HISTORY c JOIN SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY h ON h.QUERY_ID = c.QUERY_ID WHERE h.USER_NAME = 'CLAUDE_READER' AND c.START_TIME >= '2026-10-28') AS reader_ai_calls,
 (SELECT ROUND(COALESCE(SUM(c.CREDITS), 0), 3) FROM SNOWFLAKE.ACCOUNT_USAGE.CORTEX_AI_FUNCTIONS_USAGE_HISTORY c JOIN SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY h ON h.QUERY_ID = c.QUERY_ID WHERE h.USER_NAME = 'CLAUDE_READER' AND c.START_TIME >= '2026-10-28') AS reader_ai_credits,
 (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.CORTEX_AI_FUNCTIONS_USAGE_HISTORY WHERE START_TIME >= DATEADD(day, -30, CURRENT_TIMESTAMP())) AS ai_view_rows_account_30d,
 (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE USER_NAME = 'CLAUDE_READER' AND START_TIME >= '2026-10-28' AND QUERY_TEXT NOT ILIKE '%gen980-measure%' AND REGEXP_LIKE(QUERY_TEXT, '.*(^|[^A-Za-z0-9_])(AI_[A-Za-z]|SUMMARIZE_AGG|COR' || 'TEX[.]).*', 'is')) AS reader_ai_named_queries